import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals.active

def norm(value):
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

d_values = []
for r in range(2, vws.max_row + 1):
    s = norm(vws.cell(row=r, column=4).value)
    if s:
        d_values.append(s.lower())

counts = []
for r in range(2, 7):
    ref = norm(vws.cell(row=r, column=2).value).lower()
    status = norm(vws.cell(row=r, column=3).value).upper()

    if ref and status == "CANCELLED":
        count = sum(1 for d in d_values if ref in d)
    else:
        count = 0

    ws.cell(row=r, column=6).value = count
    counts.append(count)

wb.save(OUT)
print("F2:F6 =", counts)
